         backdrop-filter: blur(14px);
         box-shadow: var(--shadow);
       }

       h1 {
         margin: 0 0 8px;
         font-size: 1.9rem;
       }

       p {
         margin: 0 0 24px;
         color: var(--muted);
         line-height: 1.5;
       }

       .form-field {
         display: grid;
         gap: 14px;
         margin-bottom: 24px;
       }

       .question {
         font-size: 1.05rem;
         font-weight: 700;
       }

       .option {
         display: flex;
         align-items: center;
         gap: 12px;
         padding: 14px 16px;
         border: 1px solid rgba(148, 163, 184, 0.18);
         border-radius: 14px;
         background: rgba(30, 41, 59, 0.65);
         transition: border-color 0.2s ease, transform 0.2s ease, background-color 0.2s ease;
         cursor: pointer;
       }

       .option:hover {
         border-color: rgba(56, 189, 248, 0.55);
         transform: translateY(-1px);
       }

       .option:has(input:checked) {
         border-color: var(--accent);
         background: rgba(14, 165, 233, 0.14);
       }

       input[type="radio"] {
         margin: 0;
         accent-color: var(--accent);
         inline-size: 18px;
         block-size: 18px;
         flex: 0 0 auto;
       }

       button {
         width: 100%;
         border: 0;
         border-radius: 999px;
         padding: 14px 18px;
         font-size: 1rem;
         font-weight: 700;
         color: #020617;
         background: linear-gradient(135deg, #7dd3fc, var(--accent-strong));
         cursor: pointer;
         transition: transform 0.2s ease, box-shadow 0.2s ease;
         box-shadow: 0 14px 28px rgba(14, 165, 233, 0.28);
       }

       button:hover {
         transform: translateY(-1px);
         box-shadow: 0 18px 32px rgba(14, 165, 233, 0.35);
       }

       button:focus-visible,
       input:focus-visible {
         outline: 2px solid var(--accent);
         outline-offset: 3px;
       }

       .status {
         min-height: 1.25rem;
         margin-top: 16px;
         color: var(--accent);
         font-weight: 600;
       }
     </style>
   </head>
   <body>
     <main class="card">
       <h1>Notification Settings</h1>
       <p>Select the one way you would like us to contact you.</p>

       <form id="notification-form">
         <div class="form-field">
           <div class="question">How do you prefer to receive notifications?</div>

           <label class="option">
             <input type="radio" name="notificationPreference" value="Email" required />
             <span>Email</span>
           </label>

           <label class="option">
             <input type="radio" name="notificationPreference" value="SMS" />
             <span>SMS</span>
           </label>

           <label class="option">
             <input type="radio" name="notificationPreference" value="Push Notifications" />
             <span>Push Notifications</span>
           </label>
         </div>

         <button type="submit">Submit</button>
         <div class="status" id="status" aria-live="polite"></div>
       </form>
     </main>

     <script>
       const form = document.getElementById("notification-form");
       const status = document.getElementById("status");

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         const data = new FormData(form);
         const choice = data.get("notificationPreference");
         status.textContent = choice
           ? `Preference saved: ${choice}`
           : "Please choose one notification method.";
       });
     </script>
   </body>
 </html>

